import{_ as o,a0 as i,w as m,s as w,ao as a,I as n,x as t,a1 as l,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"寄予厚望——Semplice 5搶先看 | LCTT x X-CMD","titleTemplate":false,"description":"寄予厚望——Semplice 5搶先看 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"寄予厚望——Semplice 5搶先看 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"寄予厚望——Semplice 5搶先看 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Semplice 5 review – High Hopes","title":"寄予厚望——Semplice 5搶先看","tag":"201310","desc":""},"relativePath":"201310/Semplice 5 review – High Hopes.md","filePath":"[post].md"}'),r={name:"201310/Semplice 5 review – High Hopes.md"};function u(d,p,x,c,g,S){const e=i("Link");return m(),w("div",null,[p[17]||(p[17]=a('<h1 id="寄予厚望——semplice-5搶先看" tabindex="-1">寄予厚望——Semplice 5搶先看 <a class="header-anchor" href="#寄予厚望——semplice-5搶先看" aria-label="Permalink to “寄予厚望——Semplice 5搶先看”">​</a></h1><p>有時，我會嘗試一個看起來還不錯的桌面發行版，因為我想看看它到底有多好，能否為Linux桌面世界帶來些許新鮮空氣。所以，這次我將目標瞄向了Semplice，一個基於Debian不穩定分支的桌面發行版。</p><p>據説它的名字源於“simple”，開發者們將其解釋演繹為“KISS原則(KISS principle)”。（譯者注，KISS原則，Keep It Simple, Stupid，直譯為“保持簡單、愚蠢”，你可以理解為“簡約不簡單”，囧）</p><p>當第一次面對以KISS原則設計的發行版時，我並沒有感到太意外，因為它常常就意味着一個“皮包骨頭系統”，用户得親自矯正幾乎每一個零件，才能讓這種系統勉強工作。</p><p>所以，在本次短暫的“搶先看”中，我將帶大家一起重點測試Semplice 5的安裝過程，看看它是否值得我向我的新手用户讀者們推薦，（本次測試使用2013年9月8日發佈的最新版本）。</p><p>閒話少敍，開整！</p><p><strong>安裝程序</strong>擁有易於控制的圖形化界面，風格與Ubuntu類似。支持自動分區和手動分區。如下圖所示，可以看到分區這一步的兩個選項。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceInstall1-600x410.png" alt=""></p><p>選擇自動分區，安裝程序會自動創建兩個分區，一個是Swap交換分區，另一個為主分區。如下圖</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceInstall3-600x419.png" alt=""></p><p>不幸的是，自動分區模式更像是半自動，因為在上圖的步驟中，用户需要手動設置掛載點。雖然設置掛載點只是個很簡單的工作，但這還是足以讓我們在所謂的“自動分區”上標一個“囧”字。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceInstall2-600x410.png" alt=""></p><p>下圖中，設置用户賬户時，可以看到是否允許使用傳統root賬户的選項。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceInstall-600x413.png" alt=""></p><p>所有的選項步驟完成後，安裝程序開始正式安裝，接下來我們可以喝杯茶發發呆。整個安裝程序比較簡單，只是它並沒有“高級選項”。而目前，“高級選項”已經成為Ubuntu安裝程序的標準組成部分。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceInstall5-600x435.png" alt=""></p><p>下圖中，你可以選擇是否打開某些功能。這些功能在安裝完成後也可以隨時修改。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceInstall4-600x410.png" alt=""></p><p>對其中任意一項功能，你還可以進行更詳細的自定義設置。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceDesktop4-600x442.png" alt=""></p><p>安裝完成，系統重啓後，你應該會看到下圖中的登錄界面。順便一提，界面很漂亮，贊一個。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceLogin1-600x450.png" alt=""></p><p>登錄之後，可以看到桌面使用的是Openbox窗口管理器，這是一款最輕量級的窗口管理器，對於新手用户來説可能並不是特別適應。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceDesktop-600x450.png" alt=""></p><p>默認情況下，在桌面或底部面板上點擊鼠標右鍵可以呼出菜單欄。如下圖所示，有4個桌面或者説工作台供用户選擇。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceDesktop5-600x451.png" alt=""></p><p>由於遵循KISS原則，標準路徑中的home目錄是不存在的，你需要自己創建他們，汗~。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceFM-598x475.png" alt=""></p><p>再來看看應用程序，大部分用户都需要的一些標準應用程序默認已經安裝好。默認安裝的Web瀏覽器為Chromium。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceTaskM1-600x450.png" alt=""></p><p>Semplice 5 默認並不安裝辦公套件，因此需要我們自己安裝一個，根據倉庫中的記錄，我們可以選擇LibreOffice 4.1.1。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceDesktop8-600x450.png" alt=""></p><p>安裝新程序或管理已有程序的時候，可以使用圖形界面應用程序管理器 Synaptic Package Manager。它不像深度Linux軟件中心那樣有華麗的界面，但可以完成同樣的工作。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceDesktop7-600x451.png" alt=""></p><p>系統還在菜單中提供了一些Web應用程序（例如Facebook和Twitter），你也可以通過該發行版提供的工具添加其他Web應用。只需要按照下圖所示，在命令列中輸入命令（oneslip-add-app gtk）就可以了。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceOneslip.png" alt=""></p><p>除了上面提到的兩款管理器，系統還提供了其他圖形化界面管理器。其中一個就是“服務設置管理器”，用户可以通過它來管理系統服務。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceDesktop6-354x475.png" alt=""></p><p>另外一個是“任務管理器”。目前絕大部分Linux發行版上都已經配備了標準的圖形化任務管理器，很高興在一款以KISS原則設計的Linux發行版上，我們同樣也能看到。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceTaskM-546x475.png" alt=""></p><p>下圖中，顯示的是網絡連接設置界面，用户可以為網絡接口指定一個防火牆區域。但問題是提供該功能的防火牆程序FirewallD根本就沒有安裝，儘管用户可以從倉庫中自行安裝，也許是為了遵循KISS原則，但是默認連最基本的安全程序都沒有，這樣的發行版顯然對安全問題非常不重視。</p><p><img src="http://www.linuxbsdos.com/wp-content/uploads/2013/09/SempliceNM-468x475.png" alt=""></p><p><strong>Chakra</strong>是我見到的第一個以KISS原則設計的Linux發行版，隨着時間推移，開發者們已經漸漸改變立場，做出一些默認功能上的改進。這期間我學到的一件事就是，像Semplice這樣的發行版並不是為新手用户而設計，它們更適合那些老用户——偏好資源友好、風格簡約樸素的系統。</p>',43)),n("p",null,[p[2]||(p[2]=n("strong",null,"相關源",-1)),p[3]||(p[3]=t(" 下載安裝32位、64位系統ISO鏡像點擊",-1)),l(e,{href:"http://semplice-linux.org/download"},{default:s(()=>[...p[0]||(p[0]=[t("這裏",-1)])]),_:1}),p[4]||(p[4]=t("。閲讀發佈公告點擊",-1)),l(e,{href:"http://semplice-linux.org/blog/2013/09/semplice-5-released"},{default:s(()=>[...p[1]||(p[1]=[t("這裏",-1)])]),_:1}),p[5]||(p[5]=t("。",-1))]),p[18]||(p[18]=n("hr",null,null,-1)),n("p",null,[p[7]||(p[7]=t("via: ",-1)),l(e,{href:"http://www.linuxbsdos.com/2013/09/27/semplice-5-review-high-hopes/"},{default:s(()=>[...p[6]||(p[6]=[t("http://www.linuxbsdos.com/2013/09/27/semplice-5-review-high-hopes/",-1)])]),_:1})]),n("p",null,[p[10]||(p[10]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...p[8]||(p[8]=[t("LCTT",-1)])]),_:1}),p[11]||(p[11]=t(" 原創翻譯，",-1)),l(e,{href:"http://linux.cn/portal.php"},{default:s(()=>[...p[9]||(p[9]=[t("Linux中國",-1)])]),_:1}),p[12]||(p[12]=t(" 榮譽推出",-1))]),n("p",null,[p[15]||(p[15]=t("譯者：",-1)),l(e,{href:"http://linux.cn/space/14801"},{default:s(()=>[...p[13]||(p[13]=[t("Mr小眼兒",-1)])]),_:1}),p[16]||(p[16]=t(" 校對：",-1)),l(e,{href:"http://linux.cn/space/wxy"},{default:s(()=>[...p[14]||(p[14]=[t("wxy",-1)])]),_:1})])])}const h=o(r,[["render",u]]);export{T as __pageData,h as default};
